var ENT=[["FAISS", "Efficient dense-vector similarity search."], ["HNSW", "Graph-based approximate nearest neighbors."], ["Pinecone", "Managed vector database for RAG."], ["Vespa", "Serving search and ML at scale."], ["Apache Lucene", "The Java search library underneath it all."], ["OpenSearch", "Community search and analytics suite."], ["Sphinx Search", "SQL-friendly full-text engine."]];
